with c as (select ?1 as value), aliases as (select distinct json_extract(j.value,'$.text') collate binary as text from c,json_each(c.value,'$.terms') as j where json_extract(j.value,'$.id')<>json_extract(c.value,'$.preferredTerm.id') order by text collate binary), rendered as (select '{"kind":"concept_identity_v1","preferred_term":'||data_json_quote_v1(json_extract(c.value,'$.preferredTerm.text'))||',"aliases":['||coalesce((select group_concat(data_json_quote_v1(text),',') from aliases),'')||'],"label":'||data_json_quote_v1(json_extract(c.value,'$.label'))||',"explanation":'||data_json_quote_v1(json_extract(c.value,'$.explanation'))||',"disambiguation":'||data_json_quote_v1(json_extract(c.value,'$.disambiguation'))||',"domain":'||data_json_quote_v1(json_extract(c.value,'$.domain'))||',"tradition":'||data_json_quote_v1(json_extract(c.value,'$.tradition'))||',"period":'||data_json_quote_v1(json_extract(c.value,'$.period'))||'}' as text from c) select text,data_sha256_v1(text),'concept-identity-v1' from rendered